        &self,
        end: bool,
        label: &'static str,
        active: bool,
        p: Palette,
        cx: &Context<Self>,
    ) -> Stateful<Div> {
        let radius = Theme::global(cx).tokens.radius.full;
        row()
            .id(if end { "center-end" } else { "center-commit" })
            .debug_selector(move || {
                if end {
                    "center-end".into()
                } else {
                    "center-commit".into()
                }
            })
            .flex_1()
            .h(px(38.))
            .justify_center()
            .min_w_0()
            .rounded(radius)
            .text_size(px(14.))
            .bg(if end { p.shell } else { p.p.ink })
            .text_color(if end { p.p.ink } else { p.p.inverse })
            .when(active, |e| {
                e.role(Role::Button)
                    .aria_label(label)
                    .track_focus(if end {
                        &self.focus.end
                    } else {
                        &self.focus.commit
                    })
                    .cursor_pointer()
                    .hover(move |s| s.bg(if end { p.selected } else { p.p.secondary }))
