        assert_eq!(events.borrow()[0].as_ref().unwrap().mode.as_ref(), "deep");
        tick(w, 50 * 60 * 1000);
        assert_eq!(events.borrow().len(), 2);
        assert!(events.borrow()[1].is_none());
        tick(w, 50 * 60 * 1000);
        assert_eq!(events.borrow().len(), 2);
    }

    #[test]
